/// The add-a-link form: which Diamond, in what relation, and optionally why.
///
/// Everything typed is held in `linkForm` rather than read back out of the
/// DOM, so a repaint under a half-filled form restores it instead of emptying
/// it. Escape closes the form; a blur does not, because moving between the
/// fields of a form is not leaving it.
function linkAddForm(diamondId, selfRef) {
	var wrap = document.createElement('div');
	wrap.className = 'link-form';
	wrap.id = 'link-form';

	var err = document.createElement('div');
	err.className = 'link-err';
	err.id = 'link-err';

	// 1. Which Diamond, found the way the rail is found: by typing part of
	//    its name. Every Diamond but this one is offered, because the store
	//    rejects a link from a thing to itself.
	var pickField = document.createElement('div');
	pickField.className = 'link-field';
	var pickLbl = document.createElement('div');
	pickLbl.className = 'link-label';
	pickLbl.textContent = t('link.pick_label');
	var pick = document.createElement('input');
	pick.className = 'link-pick';
	pick.id = 'link-pick';
	pick.type = 'text';
	pick.autocomplete = 'off';
	pick.spellcheck = false;
	pick.placeholder = t('link.pick_ph');
	pick.value = pg.linkForm.query || '';
	pick.setAttribute('aria-label', t('link.pick_label'));
	var picks = document.createElement('div');
	picks.className = 'link-picks';
	picks.id = 'link-picks';
	var chosen = document.createElement('div');
	chosen.className = 'link-chosen';
	chosen.id = 'link-chosen';
	pickField.appendChild(pickLbl);
	pickField.appendChild(pick);
	pickField.appendChild(picks);
	pickField.appendChild(chosen);

	/// Redraw the picker alone, so typing never rebuilds the form under the
	/// cursor.
	function paintPicks() {
		chosen.innerHTML = '';
		picks.innerHTML = '';
		if (pg.linkForm.target) {
			pick.style.display = 'none';
			picks.style.display = 'none';
			chosen.style.display = '';
			var lbl = document.createElement('span');
			lbl.className = 'link-chosen-name';
			lbl.textContent = pg.linkForm.target.name;
			var change = document.createElement('button');
			change.className = 'link-change';
			change.id = 'link-change';
			change.type = 'button';
			change.textContent = t('link.change_pick');
			change.addEventListener('click', function () {
				pg.linkForm.target = null;
				paintPicks();
				pick.focus();
			});
			chosen.appendChild(lbl);
			chosen.appendChild(change);
			return;
		}
		pick.style.display = '';
		picks.style.display = '';
		chosen.style.display = 'none';
		var q = (pg.linkForm.query || '').trim().toLowerCase();
		var pool = pg.diamonds.filter(function (x) { return x.id !== diamondId; });
		if (!pool.length) {
			var bare = document.createElement('div');
			bare.className = 'link-none';
			bare.textContent = t('link.pick_empty');
			picks.appendChild(bare);
			return;
		}
		var hits = pool.filter(function (x) {
			return !q || (x.name || '').toLowerCase().indexOf(q) !== -1;
		}).slice(0, 8);
		if (!hits.length) {
			var no = document.createElement('div');
			no.className = 'link-none';
			no.textContent = t('link.pick_none');
			picks.appendChild(no);
			return;
		}
		hits.forEach(function (f) {
			var b = document.createElement('button');
			b.className = 'link-pick-hit';
			b.type = 'button';
			b.dataset.id = f.id;
			b.textContent = f.name;            // escaped via textContent (H5)
			b.addEventListener('click', function () {
				pg.linkForm.target = { id: f.id, name: f.name };
				err.textContent = '';
				paintPicks();
				var relBox = document.getElementById('link-rel');
				if (relBox) relBox.focus();
			});
			picks.appendChild(b);
		});
	}
	pick.addEventListener('input', function () {
		pg.linkForm.query = pick.value;
		paintPicks();
	});

	// 2. The relations, as chips. A link carries a SET, and this box used to
	//    take one line of free text -- so the only way to say two things was to
	//    type a comma and hope, and what came back was printed as one word with
	//    a comma in it. Edited the way the Graph edits the same field, and the
	//    way a Diamond's tags are edited: close a chip to drop it, click a
	//    suggestion to take it, type a word that is nobody's suggestion.
	//    `linkForm.rel` stays the STORED string throughout, so a repaint under a
	//    half-filled form restores the chips and `add_link` is handed what it
	//    always was.
	var relField = document.createElement('div');
	relField.className = 'link-field';
	var relLbl = document.createElement('div');
	relLbl.className = 'link-label';
	relLbl.textContent = t('link.rel_label');
	// The two rows' layout is set here rather than in the stylesheet: each is a
	// single flex line living only inside this form, and a rule in the sheet
	// would be a rule other surfaces could reach for and drift on.
	var relChips = document.createElement('div');
	relChips.className = 'link-rel-chips';
	relChips.id = 'link-rel-chips';
	relChips.style.cssText = 'display:flex;flex-wrap:wrap;align-items:center;gap:4px';
	var relRow = document.createElement('div');
	relRow.className = 'link-rel-add';
	relRow.style.cssText = 'display:flex;align-items:center;gap:4px';
	var relIn = document.createElement('input');
	relIn.className = 'link-rel-input';
	relIn.id = 'link-rel';
	relIn.type = 'text';
	relIn.autocomplete = 'off';
	relIn.spellcheck = false;
	relIn.maxLength = linkRelMax();
	relIn.placeholder = t('graph.rel_add_ph');
	relIn.setAttribute('aria-label', t('link.rel_label'));
	relIn.style.flex = '1';       // the sheet gives it width:100%, which would push `+` off
	relIn.style.minWidth = '0';
	var relAdd = document.createElement('button');
	relAdd.className = 'link-sug link-rel-add-btn';
	relAdd.id = 'link-rel-add';
	relAdd.type = 'button';
	relAdd.textContent = '+';
	relAdd.title = t('graph.rel_add');
	relAdd.setAttribute('aria-label', t('graph.rel_add'));
	relRow.appendChild(relIn);
	relRow.appendChild(relAdd);
	var sug = document.createElement('div');
	sug.className = 'link-rel-sug';
	sug.id = 'link-rel-sug';
	sug.title = t('link.rel_sug_help');
	var relHint = document.createElement('div');
	relHint.className = 'link-err link-rel-hint';
	relHint.id = 'link-rel-hint';

	/// The relations chosen so far, read back from what will be stored.
	function relsChosen() { return linkRels(pg.linkForm.rel); }

	/// Take a word onto the link. False when it was refused for want of room,
	/// which is the one refusal that has to be said out loud: the store would
	/// truncate, and half a relation is a relation nobody wrote.
	function addRel(word) {
		var w = linkRelTidy(word);
		relHint.textContent = '';
		if (!w) return true;
		var have = relsChosen();
		if (have.indexOf(w) !== -1) { relIn.value = ''; paintRels(); return true; }
		if (linkRelsToStore(have.concat([w])).length > linkRelMax()) {
			relHint.textContent = t('graph.rel_full', { n: linkRelMax() });
			return false;
		}
		pg.linkForm.rel = linkRelsToStore(have.concat([w]));
		relIn.value = '';
		paintRels();
		return true;
	}

	/// Draw the chosen relations and whatever suggestions are left.
	function paintRels() {
		var have = relsChosen();
		relChips.textContent = '';
		if (!have.length) {
			var bare = document.createElement('span');
			bare.className = 'link-none';
			bare.textContent = t('graph.rel_none');
			relChips.appendChild(bare);
		}
		have.forEach(function (word) {
			var c = tagChip(word, 'link-rel');
			var x = document.createElement('button');
			x.className = 'tag-x';
			x.type = 'button';
			x.textContent = '×';
			x.title = t('graph.rel_remove', { rel: word });
			x.setAttribute('aria-label', t('graph.rel_remove', { rel: word }));
			x.addEventListener('click', function () {
				pg.linkForm.rel = linkRelsToStore(relsChosen().filter(function (u) { return u !== word; }));
				relHint.textContent = '';
				paintRels();
			});
			c.appendChild(x);
			relChips.appendChild(c);
		});
		// A suggestion for a word the link already carries offers nothing, so
		// the row shows what is still on the table and no more.
		sug.textContent = '';
		DEFAULT_REL_SUGGESTIONS.filter(function (w) { return have.indexOf(w) === -1; })
			.forEach(function (word) {
				var b = document.createElement('button');
				b.className = 'link-sug';
				b.type = 'button';
				b.dataset.rel = word;
				b.textContent = word;
				b.title = t('link.rel_use', { rel: word });
				b.addEventListener('click', function () { addRel(word); relIn.focus(); });
				sug.appendChild(b);
			});
	}

	relIn.addEventListener('keydown', function (e) {
		// A comma is the separator the store uses, so typing one ends the word
		// exactly as Enter does rather than going into it.
		if (e.key !== 'Enter' && e.key !== ',') return;
		e.preventDefault();
		e.stopPropagation();          // Enter here adds a relation, it does not save
		addRel(relIn.value);
	});
	relAdd.addEventListener('click', function () { addRel(relIn.value); relIn.focus(); });

	relField.appendChild(relLbl);
	relField.appendChild(relChips);
	relField.appendChild(relRow);
	relField.appendChild(sug);
	relField.appendChild(relHint);
	paintRels();

	// 3. The note: whatever the one word does not say.
	var noteField = document.createElement('div');
	noteField.className = 'link-field';
	var noteLbl = document.createElement('div');
	noteLbl.className = 'link-label';
	noteLbl.textContent = t('link.note_label');
	var noteIn = document.createElement('input');
	noteIn.className = 'link-note-input';
	noteIn.id = 'link-note';
	noteIn.type = 'text';
	noteIn.autocomplete = 'off';
	noteIn.maxLength = 2000;
	noteIn.placeholder = t('link.note_ph');
	noteIn.value = pg.linkForm.note || '';
	noteIn.setAttribute('aria-label', t('link.note_label'));
	noteIn.addEventListener('input', function () { pg.linkForm.note = noteIn.value; });
	noteField.appendChild(noteLbl);
	noteField.appendChild(noteIn);

	// The direction is not a choice: a link is asserted FROM the Diamond you
	// are looking at, which is the only reading of "link this to that" that
	// does not need explaining.
	var says = document.createElement('div');
	says.className = 'link-says';
	says.id = 'link-says';
	says.textContent = t('link.direction_note');

	var acts = document.createElement('div');
	acts.className = 'link-form-acts';
	var save = document.createElement('button');
	save.className = 'link-save';
	save.id = 'link-save';
	save.type = 'button';
	save.textContent = t('link.save');
	save.addEventListener('click', async function () {
		if (!pg.linkForm || !pg.linkForm.target) {
			err.textContent = t('link.need_target');
			pick.focus();
			return;
		}
		// A word typed and not added is a word the user meant, so it is taken on
		// the way out -- the same bargain the Graph's editor strikes. If it will
		// not fit, the form stays open saying so rather than saving without it.
		if (!addRel(relIn.value)) { relIn.focus(); return; }
		save.disabled = true;
		try {
			await diamondApp().add_link(diamondId, selfRef, 'diamond:' + pg.linkForm.target.id,
				pg.linkForm.rel || '', pg.linkForm.note || '', 'user');
		} catch (e) {
			save.disabled = false;
			err.textContent = friendlyError(e);
			return;
		}
		pg.linkForm = null;
		signalLinksChanged();
		bumpDiamonds();
		renderLinks();
	});
	var cancel = document.createElement('button');
	cancel.className = 'link-cancel';
	cancel.id = 'link-cancel';
	cancel.type = 'button';
	cancel.textContent = t('common.cancel');
	cancel.addEventListener('click', function () { pg.linkForm = null; renderLinks(); });
	acts.appendChild(save);
	acts.appendChild(cancel);

	wrap.appendChild(pickField);
	wrap.appendChild(relField);
	wrap.appendChild(noteField);
	wrap.appendChild(says);
	wrap.appendChild(err);
	wrap.appendChild(acts);
	paintPicks();
	return wrap;
}
// page-split: install 72

/// Propose a fold: run the reducer over the current crystal plus the
/// delta, then show the diff for the user to Accept or Reject.  Writes
/// nothing — the advisory half of the fold.

// The fold-diff review UI (renderFoldDiff) was removed 2026-09-04: a fold
// commits directly now (see `commitFold`), so there is no Accept/Reject step
// and nothing renders a pending diff.

// ── Artefacts ───────────────────────────────────────────────────────
//
// The things a stretch of work produced or consulted: files written, pages opened. They
// are not declared by anyone. Every tool call an agent makes is already recorded on the
// turn as a `tool_log` with its name and arguments, so the list is derivable — and a
// derived list cannot drift, because nobody has to remember to maintain it.
//
// Harvested at the FOLD, for two reasons. The fold is where the back-and-forth is
// deliberately dropped, so it is the last moment the tool calls still exist to read. And
// it is a moment the user has already blessed, so nothing is recorded behind their back.

/// Which tools make an artefact, and what the link says.
//
// WRITES only. An agent that reads forty files to find one thing has produced nothing,
// and forty links would drown the one that matters. `web_open` is the exception: putting
// a page on the screen is deliberate in a way a background fetch is not.
var ARTEFACT_TOOLS = {
	file_write: { arg: 'path', kind: 'file', rel: 'produced' },
	file_edit:  { arg: 'path', kind: 'file', rel: 'produced' },
	file_move:  { arg: 'to',   kind: 'file', rel: 'produced' },
	dir_create: { arg: 'path', kind: 'file', rel: 'produced' },
	web_open:   { arg: 'url',  kind: 'url',  rel: 'consulted' },
	// The declared one, and the only one that is not a side effect of doing
	// something else. It says `produced` and never `holds`: `holds` is the
	// relation the user's paperclip writes and `Files.bounds` makes into a
	// write mark, so a model that could declare a `holds` link could grant
	// itself any folder of the open root with one call and a fold. A grant is
	// a user act (2026-09-23).
	artefact_add: { arg: 'path', kind: 'file', rel: 'produced' },
};

/// The artefacts named by a run of messages, deduplicated, in first-seen order.
///
/// A malformed `args` is skipped rather than thrown on: this runs inside an accepted
/// fold, and a fold that has already been applied must not fail afterwards over a tool
/// call nobody will ever look at.
export function artefactsIn(messages) {
	var out = [], seen = {};
	(messages || []).forEach(function (m) {
		if (!m || m.role !== 'tool_log') return;
		var spec = ARTEFACT_TOOLS[m.name];
		if (!spec) return;
		var args;
		try { args = JSON.parse(m.args || '{}'); } catch (e) { return; }
		var val = args && args[spec.arg];
		if (typeof val !== 'string' || !val.trim()) return;
		var ref = spec.kind + ':' + val.trim();
		if (seen[ref]) return;
		seen[ref] = 1;
		out.push({ ref: ref, rel: spec.rel });
	});
	return out;
}

/// Record what a just-accepted fold produced, as links on the Diamond.
///
/// Never throws and never blocks the fold: the crystal is already written by the time this
/// runs, so a failure here costs a list, not the user's work. Links that already exist
/// are skipped, so re-folding the same chat does not stack duplicates.
export async function harvestArtefacts(diamondId, st) {
	try {
		var msgs = [];
		if (st.sourceRun && st.sourceRun.messages) msgs = st.sourceRun.messages;
		else if (st.chatId) {
			var chat = pg.chats.find(function (c) { return c.id === st.chatId; });
			msgs = chat ? chat.messages : [];
		}
		var found = artefactsIn(msgs);
		if (!found.length) return;

		var self = 'diamond:' + diamondId;
		var have = {}, dirs = [];
		try {
			JSON.parse(await diamondApp().links_touching(self) || '[]')
				.forEach(function (l) {
					have[l.to] = 1;
					// Every directory already attached, of ANY rel: a dir a fold
					// harvested last time counts as much as one the user marked in.
					var parsed = parseRef(l.to);
					if (parsed.kind === 'dir' && parsed.path) dirs.push(parsed.path);
				});
		} catch (e) { /* no links yet, or unreadable: treat as none */ }

		var made = 0;
		for (var i = 0; i < found.length; i++) {
			var ref = found[i].ref;
			if (have[ref]) continue;
			var parsedRef = parseRef(ref);
			// Harvest less. A file already inside an attached folder is already
			// visible there -- the folder chip says so -- so a `produced` link
			// naming it individually is the duplicate the owner was looking at,
			// not a second fact. `dev/ATTACH_CONTRACT.md` §2b.
			if (parsedRef.kind === 'file' && dirs.some(function (d) {
				return parsedRef.path === d || parsedRef.path.indexOf(d + '/') === 0;
			})) continue;
			// Dot-prefixed basenames are workspace plumbing (`.git/…`,
			// `.daimond/…`, an editor swapfile) — never a thing a person would
			// recognise as something they attached.
			var base = parsedRef.path ? parsedRef.path.split('/').pop() : '';
			if (base && base.charAt(0) === '.') continue;
			try {
				await diamondApp().add_link(diamondId, self, ref, found[i].rel, '', 'fold');
				made++;
			} catch (e) { /* one bad ref must not stop the rest */ }
		}
		// A fold makes links like any other writer, so whatever draws them is
		// told the same way.
		if (made) signalLinksChanged();
		if (pg.currentDiamond && pg.currentDiamond.id === diamondId) renderCrystal();
	} catch (e) { /* an artefact list is never worth failing a fold over */ }
}

/// Commit a proposed fold to the crystal, DIRECTLY — write the new crystal,
/// retain the raw delta, log the fold, harvest artefacts, then re-render.
///
/// ONE CLICK COMMITS (owner decision 2026-09-04): this replaced `doFoldAccept`,
/// which stashed the proposal and waited on an Accept/Reject diff. There is no
/// review now. Two guards remain, at the CALL SITES rather than here, because
/// they are not the review: a reducer that returned nothing is refused before
/// this runs, so a bad round cannot wipe the crystal. And the undo is the
/// crystal's VERSION HISTORY: `fold_apply` writes through `write_crystal_data`,
/// which snapshots a version and logs the edit, so a fold the user did not want
/// is rolled back from history rather than declined up front.
///
/// `st` is `{ base, proposed, delta, chatId, chatName, partial, sourceRun }`,
/// where `proposed` is the ENVELOPE `fold_propose` answered with — the crystal
/// and whichever of REQUIREMENTS.md, DECISIONS.md and STATE.md the reducer
/// rewrote — carried back to `fold_apply` unchanged.
/// Throws on a write failure so the caller can report it and, for a daimon
/// self-fold, NOT clear the conversation. Resolves `{ changed, version, said }`:
/// whether anything was written, the version the fold minted (its Undo), and the
/// engine's sentence about sections moved cold to make room.
export async function commitFold(diamondId, st) {
	// A fold that changes nothing writes nothing: applying it would bump the
	// version and store a duplicate delta, growing the history with nothing in it.
	// Read off the envelope's crystal, not off the envelope: the envelope also
	// carries the files, so comparing it with the crystal would never match and
	// every fold would write a version.
	if (foldChangesNothing(st)) return { changed: false, version: 0, said: '' };
	setCrystalStatus(t('fold.applying'));
	var raw = await diamondApp().fold_apply(diamondId, st.proposed, st.delta, 'fold via UI');
	var ans = {};
	try { ans = JSON.parse(raw || '{}') || {}; }
	catch (e) { ans = {}; }                      // landed; only the Undo's version is unknown
	var landed = { changed: true, version: Number(ans.version) || 0, said: String(ans.said || ''),
		files: Array.isArray(ans.files) ? ans.files.map(String) : [] };
	await harvestArtefacts(diamondId, st);
	// Record where the chat went, so the tile can say so and the user is not left
	// wondering whether the fold took. A fold of a few chosen turns is not the
	// chat going anywhere, so it leaves no such mark.
	//
	// NOT ON A DAIMON FOLDING INTO ITSELF. That conversation is cleared the moment
	// this returns (`clearDaimonSession`), so a "folded into" marker on it is a
	// mark on nothing — and its stored message-count would later match a FRESH
	// conversation of the same length and wrongly trip the "nothing new" guard,
	// refusing a fold whose content really is new. `chat.diamondId === diamondId`
	// is exactly the self-fold.
	if (st.chatId && !st.partial) {
		var chat = pg.chats.find(function (c) { return c.id === st.chatId; });
		if (chat && chat.diamondId !== diamondId) {
			var f = pg.diamonds.find(function (x) { return x.id === diamondId; });
			chat.foldedInto = { id: diamondId, name: (f && f.name) || '', at: Date.now(),
				at_len: (chat.messages || []).length };
			// Folding is a METADATA change (S-SYNC #5): stamp `metaAt` so the fold is
			// not reverted by a later turn landing from another device.
			touchChatMeta(chat);
			persistChats();
			renderSessionList();
		}
	}
	// A worker's summary that has now been applied is marked so its tile no longer
	// offers to fold the same text in a second time.
	if (st.sourceRun) {
		st.sourceRun.folded = true;
		Workers.persist();
		Workers.render();
	}
	await refreshDiamondAfterChange();
	return landed;
}

/// Would applying this proposal leave the Diamond exactly as it is?
///
/// The crystal unchanged AND no file block in the envelope. A fold that rewrote
/// only STATE.md is a real change even where the crystal came back byte for byte,
/// which is the case the old crystal-only comparison would have written off.
function foldChangesNothing(st) {
	var p = foldEnvelope(st.proposed);
	if (!p) return false;                        // unreadable: let fold_apply say so
	if (p.requirements || p.decisions || p.state) return false;
	return String(st.base || '') === String(p.crystal || '');
}

/// The envelope `fold_propose` answers with, or null when it is not one.
export function foldEnvelope(text) {
	try {
		var p = JSON.parse(String(text || ''));
		return (p && typeof p === 'object' && typeof p.crystal === 'string') ? p : null;
	} catch (e) { return null; }
}

export function install() { // page-split: install
	// page-split: install 70

	// The Terminal panel is the second: a session's fence was computed for ONE
	// Diamond's bounds, so a Diamond change ends it rather than carrying it over
	// into a workspace it was never granted.
	document.addEventListener('daimond-diamond-changed', function () {
		if (window.DaimondTerm) DaimondTerm.onDiamondChanged();
	});
	// page-split: install 71

	// Escape in the link form puts the form away. A claim held for the page's life, not a layer: the form is
	// held open in place and has no history entry, and it declines unless the keyboard is inside it.
	DaimondLayers.claim('linkform', function () {
		var a = document.activeElement;
		if (!a || !a.closest || !a.closest('#link-form')) return false;
		pg.linkForm = null;
		renderLinks();
	});
	// page-split: install 72

	// A small surface for tests, and for the graph, which wants to know when a
	// link changed without reaching into this file for it.
	window.DaimondLinks = {
		render: renderLinks,
		/// Open or close the section, then repaint it.
		toggle: function (open) {
			var on = (open === undefined) ? !footOpen('links') : !!open;
			setFootOpen('links', on);
			if (!on) pg.linkForm = null;
			return renderLinks();
		},
		changed: signalLinksChanged,
	};
} // page-split: end install
